function renderDetail(){queueMicrotask(refreshPrices);const id=location.hash.split('/')[1];const p=products.find(p=>p.id===id);if(!p){if(!catalogueReady){app.innerHTML=catalogueLoading('THE COLLECTION');return}const current=window.tradeCatalog.find(x=>x.id===id);if(current&&catalogueReady){app.innerHTML=managedPublicDetail(current);return}location.hash='collection';return}if(detailModel!==id){detailModel=id;variantIndex=0;viewIndex=0;detailQty=1;lensIndex=-1}const v=p.variants[variantIndex]||p.variants[0];if(viewIndex>=v.images.length)viewIndex=0;const im=v.images[viewIndex];document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page==='collection');if(a.dataset.page==='collection')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('.sidebar').classList.remove('open');document.querySelector('.mobile-toggle').setAttribute('aria-expanded','false');document.title=`${id} · ${v.name} — DOOK Denmark`;app.innerHTML=renderTopbar('THE ACETATE COLLECTION')+`<div class="detail-breadcrumb"><a href="#${returnPage}">← ${returnPage==='partners'?'Partner collection':'The collection'}</a><span>Frames / ${id}</span></div><section class="product-detail"><div class="detail-gallery"><div class="gallery-stage"><span class="gallery-mark">DOOK / ${id}</span><button class="zoom-image" aria-label="Enlarge ${id} product image" data-zoom><span class="detail-photo"><img class="detail-main-image" src="${im.src}" alt="${id} in ${v.name}, ${im.label}"><span class="detail-dook-layer detail-dook-left" hidden aria-hidden="true"><img alt=""></span><span class="detail-dook-layer detail-dook-right" hidden aria-hidden="true"><img alt=""></span></span></button><span class="gallery-view">${im.label}</span><button class="zoom-trigger" data-zoom aria-label="Enlarge product image">＋</button></div><div class="gallery-bottom"><div class="gallery-thumbs" aria-label="Product views">${v.images.map((pic,i)=>`<button data-view="${i}" class="${i===viewIndex?'selected':''}" aria-pressed="${i===viewIndex}" aria-label="Show ${pic.label}"><img src="${pic.src}" alt="${pic.label}"></button>`).join('')}</div><span class="image-count">0${viewIndex+1} / 0${v.images.length}</span></div></div><div class="detail-info"><h1>${id}</h1><div class="detail-option"><div class="option-label"><span>Colour</span><strong>${v.name}</strong></div><div class="colour-options" aria-label="Choose frame colour">${p.variants.map((c,i)=>`<button data-colour="${i}" style="--swatch:${c.hex}" class="${i===variantIndex?'selected':''}" aria-pressed="${i===variantIndex}" aria-label="${c.name}"><span></span></button>`).join('')}</div><span class="colour-code">${id} / ${v.code}</span></div>${lensOptions(id)}${detailPriceHTML()}${id==='A012'?'<div class="detail-size"><span>Lens size</span><span class="size-value">50 mm</span></div>':''}<div class="detail-cta">${returnPage==='partners'?`<div class="detail-quantity"><button data-detail-qty="-1" aria-label="Decrease quantity" ${detailQty===1?'disabled':''}>−</button><output>${detailQty}</output><button data-detail-qty="1" aria-label="Increase quantity" ${detailQty===100?'disabled':''}>+</button></div><button class="pill" data-detail-add>Add to enquiry <span>↗</span></button>`:'<button class="pill" data-enquire>Enquire about this frame <span>↗</span></button>'}</div><p class="detail-support">${returnPage==='partners'?'Your colour selection is included in the enquiry.':'Ask your optician about fitting and availability.'}</p><div class="detail-facts"><span>Designed in Denmark</span><span>Acetate frame</span></div><details class="detail-accordion"><summary>A frame. More possibilities.<span>+</span></summary><p>Match your DOOK click-on to the frame model and lens size.</p><button class="text-button" data-enquire>Ask about matching DOOKs ↗</button></details></div></section><section class="section related"><div class="section-title"><div><h2>More frames.</h2></div><a class="text-link" href="#collection">All frames ↗</a></div>${productCards(products.filter(x=>x.id!==id).slice(0,3))}</section>`+footer();updateGalleryImage();for(const variant of p.variants)for(const photo of variant.images){const preload=new Image();preload.src=photo.src}}
// Update only the existing controls and image; the page, focus and scroll stay intact.
function updateDetail(){
 queueMicrotask(refreshPrices);
 const p=products.find(p=>p.id===detailModel),v=p.variants[variantIndex];
 if(viewIndex>=v.images.length)viewIndex=0;
 document.title=`${p.id} · ${v.name} — DOOK Denmark`;
 document.querySelector('.option-label strong').textContent=v.name;
 document.querySelector('.colour-code').textContent=`${p.id} / ${v.code}`;
 document.querySelectorAll('[data-colour]').forEach(b=>{const selected=Number(b.dataset.colour)===variantIndex;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});
 const thumbs=document.querySelector('.gallery-thumbs');
 // Retain thumbnail buttons when the view count is unchanged, including keyboard focus.
 if(thumbs.children.length!==v.images.length)thumbs.innerHTML=v.images.map((pic,i)=>`<button data-view="${i}" aria-label="Show ${pic.label}"><img alt="${pic.label}"></button>`).join('');
 [...thumbs.children].forEach((b,i)=>{b.classList.toggle('selected',i===viewIndex);b.setAttribute('aria-pressed',String(i===viewIndex));b.setAttribute('aria-label',`Show ${v.images[i].label}`);b.firstElementChild.src=v.images[i].src;b.firstElementChild.alt=v.images[i].label});
 document.querySelector('.image-count').textContent=`0${viewIndex+1} / 0${v.images.length}`;
 document.querySelectorAll('[data-dook-colour]').forEach(b=>{const selected=Number(b.dataset.dookColour)===lensIndex;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});
 const selected=document.querySelector('.selected-lens');if(selected)selected.textContent=lensIndex<0?'Frame only':window.dookLenses[lensIndex].name;
 updateGalleryImage();
}
let imageRequest=0;
const clipMotion=(index,attached)=>({opacity:attached?1:0,transform:attached?'translate(0,0) scale(1) rotate(0)':`translate(${index===0?'-':'+'}12%,-38%) scale(1.09) rotate(${index===0?'-':'+'}9deg)`,filter:attached?'drop-shadow(0 0 0 transparent)':'drop-shadow(0 16px 10px #383e4244)'});
async function moveClickOns(layers,attach){
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(reduced)return;
 await Promise.all(layers.map((layer,index)=>layer.animate([clipMotion(index,!attach),clipMotion(index,attach)],{duration:attach?760:230,delay:attach?index*100:index*35,easing:attach?'cubic-bezier(.22,.8,.2,1)':'ease-in',fill:'both'}).finished.catch(()=>{})));
}
async function updateGalleryImage(){
 const request=++imageRequest,p=products.find(p=>p.id===detailModel),v=p.variants[variantIndex],im=v.images[viewIndex];
 const target=document.querySelector('.detail-main-image'),stage=document.querySelector('.gallery-stage'),photo=document.querySelector('.detail-photo');
 const layers=[...photo.querySelectorAll('.detail-dook-layer')];
 layers.forEach(layer=>layer.getAnimations().forEach(animation=>animation.cancel()));
 const lens=lensIndex<0?null:window.dookLenses[lensIndex];
 const label=lens?`${lens.name} · DOOK preview`:im.label;
 const alt=`${p.id} in ${v.name}, ${label}`;
 const current=()=>request===imageRequest&&target.isConnected;
 stage.setAttribute('aria-busy','true');
 try{
  const scene=await window.makeDookScene(p.id,im.src,lens);
  if(!current())return;
  if(layers.some(layer=>!layer.hidden))await moveClickOns(layers,false);
  if(!current())return;
  layers.forEach(layer=>{layer.hidden=true;layer.getAnimations().forEach(animation=>animation.cancel())});
  target.src=scene.base;target.dataset.zoomSrc=scene.composite;target.alt=alt;
  photo.style.aspectRatio=`${scene.width} / ${scene.height}`;
  document.querySelector('.gallery-view').textContent=label;
  document.querySelector('.preview-error')?.remove();
  if(scene.layers.length){
   await Promise.all(layers.map(async(layer,index)=>{layer.firstElementChild.src=scene.layers[index];await layer.firstElementChild.decode()}));
   if(!current())return;
   layers.forEach(layer=>layer.hidden=false);
   await moveClickOns(layers,true);
   if(!current())return;
   layers.forEach(layer=>layer.getAnimations().forEach(animation=>animation.cancel()));
  }
 }catch(error){
  if(!current())return;
  layers.forEach(layer=>{layer.hidden=true;layer.getAnimations().forEach(animation=>animation.cancel())});
  target.src=im.src;target.dataset.zoomSrc=im.src;target.alt=`${p.id} in ${v.name}`;
  document.querySelector('.gallery-view').textContent=im.label;
  if(!document.querySelector('.preview-error')){const note=document.createElement('p');note.className='preview-error';note.setAttribute('role','status');note.textContent='The DOOK preview could not load. Please select a colour to try again.';stage.after(note)}
 }finally{if(current())stage.setAttribute('aria-busy','false')}
}
function lensDescription(){return lensIndex<0?'':` · DOOK: ${window.dookLenses[lensIndex].name}`}
document.addEventListener('click',e=>{
 const c=e.target.closest('[data-colour]');if(c){variantIndex=Number(c.dataset.colour);updateDetail()}
 const view=e.target.closest('[data-view]');if(view){viewIndex=Number(view.dataset.view);updateDetail()}
 const lens=e.target.closest('[data-dook-colour]');if(lens){lensIndex=Number(lens.dataset.dookColour);updateDetail()}
 const q=e.target.closest('[data-detail-qty]');if(q){detailQty=Math.max(1,Math.min(100,detailQty+Number(q.dataset.detailQty)));document.querySelector('.detail-quantity output').textContent=detailQty;document.querySelector('[data-detail-qty="-1"]').disabled=detailQty===1;document.querySelector('[data-detail-qty="1"]').disabled=detailQty===100}
 if(e.target.closest('[data-enquire]')){const p=products.find(p=>p.id===detailModel),v=p.variants[variantIndex];contactDraft=`Hello DOOK,\n\nI would like to know more about ${p.id} in ${v.name} (${v.code})${p.id==='A012'?', lens size 50 mm':''}${lensDescription()} and its matching click-ons.\nPlease confirm the compatible lens size and availability.\n\n`;location.hash='contact'}
 if(e.target.closest('[data-detail-add]')){const p=products.find(p=>p.id===detailModel),v=p.variants[variantIndex];const key=`${p.id} · ${v.code} · ${v.name}${p.id==='A012'?' · 50 mm':''}${lensDescription()}`;bag[key]=(bag[key]||0)+detailQty;const toast=document.querySelector('.toast');toast.innerHTML=`${detailQty} × ${p.id} added. <a href="#partners" style="text-decoration:underline">View enquiry ↗</a>`;toast.hidden=false;setTimeout(()=>toast.hidden=true,4500)}
 if(e.target.closest('[data-zoom]')){const p=products.find(p=>p.id===detailModel),v=p.variants[variantIndex],shown=document.querySelector('.detail-main-image');lastFocus=document.activeElement;document.querySelector('#modal-content').innerHTML=`<span class="eyebrow" id="modal-title">${p.id} · ${v.name}</span><div class="enlarged-product"><img src="${shown.dataset.zoomSrc||shown.src}" alt="${shown.alt}"></div><p>${v.images[viewIndex].label}${lensDescription()}</p>`;document.querySelector('#modal').hidden=false;document.body.style.overflow='hidden';document.querySelector('.close').focus()}
});

